```csharp
public int MaximumDisplayWidth
{
    get { return maximumDisplayWidth; }
    set
    {
        if (value < 1) throw new ArgumentOutOfRangeException("value", "Maximum display width must be greater than zero.");

        maximumDisplayWidth = value;
    }
}
```

